                    q("¿Qué hace el «bribón sensato»?", "cumple las reglas, salvo cuando puede romperlas sin ser descubierto", ["cumple las reglas, salvo cuando puede romperlas sin ser descubierto", "rompe siempre las reglas", "cumple siempre las reglas por deber"]),
